let currentLang = localStorage.getItem('furnicore_lang') || 'ru';
function t(key){ return (I18N[currentLang] && I18N[currentLang][key]) || I18N.ru[key] || key; }
// v6.87: для текста, который навсегда сохраняется в Историю/аудит (в отличие от текста
// интерфейса, который просто отображается и может меняться при смене языка), нужен язык,
// который НЕ зависит от currentLang в момент действия — иначе история одного заказа могла
// оказаться на разных языках в зависимости от того, что было выбрано в момент каждого клика.
function tRu(key){ return I18N.ru[key] || key; }
